// Declarations from `@solidjs/signals@2.0.0-rc.21`: `flush` `dist/types/core/scheduler.d.ts:448-449`;
// `createEffect` `dist/types/signals.d.ts:427` with `EffectFunction` and `EffectBundle` (options dropped, `ComputeFunction`
// reduced to its synchronous form). No `action`: SC2006 does not ask in this fixture.
export type EffectFunction<Prev, Next extends Prev = Prev> = (v: Next, p?: Prev) => (() => void) | void;
export type EffectBundle<Prev, Next extends Prev = Prev> = {
    effect: EffectFunction<Prev, Next>;
    error: (err: unknown, cleanup: () => void) => void;
};
export declare function flush(): void;
export declare function flush<T>(fn: () => T): T;
export declare function createEffect<const T>(compute: (v: undefined | NoInfer<T>) => T, effectFn: EffectFunction<NoInfer<T>, T> | EffectBundle<NoInfer<T>, T>): void;
